let lang='fr';try{lang=localStorage.getItem('candy-language')||'fr'}catch{}if(!T[lang])lang='fr';
let projects=[],category='all',query='',status='all',lastCatalog='home';
const view=document.getElementById('view'),sidebar=document.getElementById('sidebar');
const escape=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const tr=k=>T[lang][k],txt=v=>v[lang];
function wa(project){return 'https://wa.me/33769232538?text='+encodeURIComponent(lang==='fr'?`Bonjour Candy, je souhaite échanger sur ${project||'mon projet'}.`:`Hello Candy, I would like to discuss ${project||'my project'}.`)}
const ext=(url,label,cls='btn')=>`<a class="${cls}" href="${escape(url)}" target="_blank" rel="noopener noreferrer">${label}</a>`;
function contact(){return `<section class="contact-band"><div><h2>${tr('contactTitle')}</h2><p>${tr('contactText')}</p></div><div class="buttons">${ext(wa(),tr('whatsapp'),'btn orange')}${ext('https://calendly.com/candy-jones-effigestions',tr('calendly'))}</div></section>`}
function footer(){return `<footer class="footer"><span>${tr('footer')}</span><span>${tr('footerNote')}</span></footer>`}
function top(){return `<div class="topline"><span class="eyebrow">${tr('top')}</span>${ext('https://calendly.com/candy-jones-effigestions',tr('book'),'')}</div>`}
function updateShell(){document.documentElement.lang=lang;document.title=lang==='fr'?'Candy’s Universe — Des idées aux outils utiles':'Candy’s Universe — From ideas to useful tools';document.querySelectorAll('[data-t]').forEach(el=>el.textContent=tr(el.dataset.t));document.querySelectorAll('[data-lang]').forEach(el=>el.setAttribute('aria-pressed',el.dataset.lang===lang));document.getElementById('side-contact').href=wa();const keys=['all','business','daily','family','community'];document.getElementById('nav').innerHTML=keys.map(k=>`<a class="${category===k?'active':''}" ${category===k?'aria-current="page"':''} href="#${k==='all'?'home':'category/'+k}"><span>${tr(k)}</span><span>${k==='all'?projects.length:projects.filter(p=>p.category===k).length}</span></a>`).join('');sidebar.setAttribute('aria-label',lang==='fr'?'Navigation principale':'Main navigation')}
function hero(){return `<section class="hero"><div class="hero-copy"><h1>${tr('hero')}</h1><p>${tr('heroText')}</p><div class="buttons"><a class="btn primary" href="#collection" id="explore-link">${tr('exploreBtn')}</a>${ext(wa(),tr('ideaBtn'))}</div></div><div class="hero-feature"><div class="feature-head"><span class="eyebrow">${tr('featured')}</span><h2>MonPlatDuJour</h2><p>${tr('featureTag')}</p></div><div class="feature-body"><p>${tr('featureBody')}</p><a href="#project/monplatdujour" class="text-link">${tr('discoverService')}</a></div></div></section><div class="intro-strip"><p>${tr('strip')}</p><span class="count"><b>${projects.length}</b>${tr('creations')}</span></div>`}
function card(p){const initials=p.id==='60before9'?'60':p.name==='NIA'?'N':p.name.split(/[ ·]/).filter(Boolean).map(x=>x[0]).slice(0,2).join('');return `<article class="card ${p.color}"><div class="card-top"><div class="card-top-line"><span class="kind">${escape(txt(p.kind))}</span><span class="monogram" aria-hidden="true">${escape(initials)}</span></div><h3><a href="#project/${p.id}">${escape(p.name)}</a></h3></div><div class="card-body"><span class="status ${p.status}">${tr(p.status)}</span><p>${escape(txt(p.tag))}</p><a class="card-link" href="#project/${p.id}" aria-label="${escape(tr('see')+' : '+p.name)}"><span>${tr('see')}</span><span aria-hidden="true">↗</span></a></div></article>`}
function normalize(s){return s.replace(/œ/g,'oe').replace(/Œ/g,'OE').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase()}
function filter(){const q=normalize(query);const filtered=projects.filter(p=>(category==='all'||p.category===category)&&(status==='all'||p.status===status)&&normalize([p.name,txt(p.tag),txt(p.kind),txt(p.audience),...p.stack,...p.features.map(txt)].join(' ')).includes(q));document.getElementById('grid').innerHTML=filtered.length?filtered.map(card).join(''):`<div class="empty"><p>${tr('empty')}</p><button class="btn" id="reset">${tr('reset')}</button></div>`;document.getElementById('results').textContent=`${filtered.length} ${filtered.length===1?tr('result'):tr('results')}`;document.getElementById('reset')?.addEventListener('click',()=>{query='';status='all';document.getElementById('search').value='';document.getElementById('status-filter').value='all';filter()})}
function catalog(){lastCatalog=category==='all'?'home':'category/'+category;view.innerHTML=`<div class="page">${top()}${category==='all'?hero():''}<section id="collection" aria-labelledby="collection-title"><div class="section-title"><div><h2 id="collection-title">${category==='all'?tr('collection'):tr(category)}</h2><p>${category==='all'?tr('collectionSub'):T[lang].categoryDescriptions[category]}</p></div></div><div class="tools"><div class="search-wrap"><span aria-hidden="true">⌕</span><input id="search" type="search" aria-label="${tr('searchLabel')}" placeholder="${tr('search')}" value="${escape(query)}"></div><select id="status-filter" aria-label="${tr('statusLabel')}"><option value="all">${tr('anyStatus')}</option>${['service','operational','demo','test','build','concept','live'].map(s=>`<option value="${s}" ${status===s?'selected':''}>${tr(s)}</option>`).join('')}</select></div><p id="results" class="results-count" aria-live="polite"></p><div id="grid" class="grid"></div></section>${contact()}${footer()}</div>`;document.getElementById('search').addEventListener('input',e=>{query=e.target.value;filter()});document.getElementById('status-filter').addEventListener('change',e=>{status=e.target.value;filter()});document.getElementById('explore-link')?.addEventListener('click',e=>{e.preventDefault();document.getElementById('collection').scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth'})});filter()}
function detail(p){view.innerHTML=`<div class="page">${top()}<a class="back" href="#${lastCatalog}">${tr('back')}</a><header class="detail-header ${p.color}"><p class="eyebrow">${escape(txt(p.kind))}</p><h1>${escape(p.name)}</h1><p>${escape(txt(p.tag))}</p></header><div class="detail-layout"><div><section class="detail-section"><h2>${tr('who')}</h2><p>${escape(txt(p.audience))}</p></section><section class="detail-section"><h2>${tr('problem')}</h2><p>${escape(txt(p.problem))}</p></section><section class="detail-section"><h2>${tr(['concept','build'].includes(p.status)?'plannedFeatures':'features')}</h2><ul class="feature-list">${p.features.map((f,i)=>`<li><span aria-hidden="true">0${i+1}</span>${escape(txt(f))}</li>`).join('')}</ul></section>${p.example?`<section class="detail-section"><h2>${tr('example')}</h2><p>${escape(txt(p.example))}</p></section>`:''}<section class="detail-section"><h2>${tr('story')}</h2><p>${escape(txt(p.story))}</p></section></div><aside class="detail-aside"><span class="status ${p.status}">${tr(p.status)}</span><h2>${tr('where')}</h2><p class="update-date">${lang==='fr'?'Mise à jour : 1er novembre 2026':'Updated: 1 November 2026'}</p><p>${escape(txt(p.note))}</p>${p.url?ext(p.url,tr(p.linkType==='catalog'?'catalog':'open'),'btn primary'):''}${ext(wa(p.name),tr(p.id==='assistpro'?'join':['60before9','mailbee','seniorcare','entrenous'].includes(p.id)?'request':'discuss'),'btn '+(p.url?'':'primary'))}${ext('https://calendly.com/candy-jones-effigestions',tr('calendly'))}<details><summary>${tr('technical')}</summary><div class="stack" style="margin-top:12px">${p.stack.map(s=>`<span>${escape(s)}</span>`).join('')}</div></details></aside></div>${contact()}${footer()}</div>`;document.title=p.name+' · Candy’s Universe'}
function about(){view.innerHTML=`<div class="page about-page">${top()}<p class="eyebrow">${tr('aboutKicker')}</p><h1>${tr('aboutTitle')}</h1><p class="about-intro">${tr('aboutText')}</p><p class="about-intro">${tr('aboutText2')}</p><section class="process">${[1,2,3].map(i=>`<div><span>0${i}</span><h2>${tr('step'+i)}</h2><p>${tr('step'+i+'text')}</p></div>`).join('')}</section><a class="btn primary" href="#home">${tr('browse')}</a>${contact()}${footer()}</div>`}
function render(scroll=true){const hash=location.hash.slice(1)||'home';const parts=hash.split('/');if(parts[0]==='category'&&['business','daily','family','community'].includes(parts[1]))category=parts[1];else if(hash==='home')category='all';updateShell();if(parts[0]==='project'){const p=projects.find(p=>p.id===parts[1]);p?detail(p):catalog()}else if(hash==='about')about();else catalog();sidebar.classList.remove('open');document.getElementById('menu-toggle').setAttribute('aria-expanded','false');if(scroll){window.scrollTo(0,0);document.getElementById('main').focus({preventScroll:true})}}
document.querySelectorAll('[data-lang]').forEach(b=>b.addEventListener('click',()=>{lang=b.dataset.lang;try{localStorage.setItem('candy-language',lang)}catch{}render(false)}));
document.getElementById('menu-toggle').addEventListener('click',()=>{const open=sidebar.classList.toggle('open');document.getElementById('menu-toggle').setAttribute('aria-expanded',String(open))});document.addEventListener('keydown',e=>{if(e.key==='Escape'){sidebar.classList.remove('open');document.getElementById('menu-toggle').setAttribute('aria-expanded','false')}});document.addEventListener('click',e=>{if(!sidebar.contains(e.target)&&!e.target.closest('#menu-toggle')){sidebar.classList.remove('open');document.getElementById('menu-toggle').setAttribute('aria-expanded','false')}});window.addEventListener('hashchange',()=>render());
fetch('projects.json').then(r=>{if(!r.ok)throw Error('HTTP '+r.status);return r.json()}).then(data=>{projects=data;render(false)}).catch(()=>{updateShell();view.innerHTML=`<div class="page"><p role="alert">${tr('error')}</p></div>`});
